    def apply(self, rows, account):
        result = []
        for row in rows:
            kind, acct, cents = row
            if cents < 0:
                raise ValueError("negative amount: %r" % (cents,))
            if acct == account:
                result.append((kind, acct, cents))
        return result


def balance(rows, account):
    total = 0
    for kind, acct, cents in rows:
        if acct != account:
            continue
        if kind == "deposit":
            total += cents
        elif kind == "withdraw":
            total -= cents
    return total
"}

{"path": "schedule.py", "content": "def slots(ranges, minutes):
    ordered = sorted(ranges, key=lambda r: (r[0], r[1]))
    merged = []
    for start, end in ordered:
        if merged and start - merged[-1][1] < minutes:
            if end > merged[-1][1]:
                merged[-1] = (merged[-1][0], end)
        else:
            merged.append((start, end))
    return merged


def overlaps(a, b):
    return a[0] < b[1] and b[0] < a[1]
